-- ============================================================================
-- EC3: Probabilistic Economics joins the catalog, the THIRD Economics course.
--
-- Catalog row (module 'economics'; path_order 55; prereq_slug NULL, the
-- carried-over answer "no hard prerequisite inside a module") plus the three
-- capstones and their eighteen graded fields, generated by
-- /root/ec-wip-uncertainty/gen_course.py from fields.json and the capstone
-- constants in ec3_fields.mjs. Deep seeds are three separate migrations; the
-- go-live is a fifth and is HELD until a NextGen production upload carries
-- the route /dashboard/apps/uncertainty.
--
-- THE ONE SENTENCE THE COURSE IS. A screening number becomes a decision only
-- when its range is stated honestly: percentiles are not endpoints, a sample
-- is only as reproducible as its seed, and a P-label means one thing or it
-- means nothing.
--
-- THE ENGINES. engines/economics/screening.js (the NPV Scenario Builder) and
-- engines/economics/breakeven.js (the Probabilistic Breakeven Analyzer) with
-- lib/stats, as repaired before this course in EC3-0 (engines #174 seeded
-- the Scenario Builder Monte Carlo and repaired its zero-width and short-run
-- paths, #175 moved the Suite percentile convention into the engines package,
-- #176 took the P-labels out of the triangular fit notes; Suite #477 and
-- #478 fixed the swapped risk cards and relabelled both apps).
--
-- THE CAPSTONE GRADES WHAT THE COURSE TEACHES A READER TO GET RIGHT: the
-- fitted triangle against the stated belief, the percentiles of a breakeven
-- price, the P-label mapping on an NPV (the Low case P90 reads the p10 key),
-- the two percentile rules (6.6 grading tolerances apart on this sample),
-- and what a different seed does. Every graded field was chosen at least 37
-- tolerances from any teaching-digest number and is moved beyond its
-- tolerance by the named mistakes (scratch/discriminate.mjs, 0 weak fields).
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('uncertainty', 'Probabilistic Economics', 'economics', 55, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
